export function createApp() {
  const records = new Map();
  return {
    submit: (input, actor, now) => submit(records, input, actor, now),
    approve: (id, actor, now) => approve(records, id, actor, now),
    reject: (id, reason, actor, now) => reject(records, id, reason, actor, now),
    purchase: (id, actualYen, actor, now) => purchase(records, id, actualYen, actor, now),
    detail: id => detail(records, id),
    list: () => list(records),
  };
}

import { commandContext, target } from '../validation.mjs';

export function approve(records, id, actor, now) {
  commandContext(actor, now, 'approver');
  const record = { ...target(records, id, 'submitted'), approvedAt: now, approvedBy: actor.id, status: 'approved' };
  records.set(id, record);
  return { ...record };
}

import { target } from '../validation.mjs';

export function detail(records, id) {
  return { ...target(records, id) };
}

export function list(records) {
  return [...records.values()]
    .sort((a, b) => a.id < b.id ? -1 : a.id > b.id ? 1 : 0)
    .map(record => ({ ...record }));
}

import { commandContext, positiveInteger, target } from '../validation.mjs';

export function purchase(records, id, actualYen, actor, now) {
  commandContext(actor, now, 'buyer');
  const record = {
    ...target(records, id, 'approved'), actualYen: positiveInteger(actualYen),
    purchasedAt: now, purchasedBy: actor.id, status: 'purchased',
  };
  records.set(id, record);
  return { ...record };
}

import { commandContext, target, trimmedText } from '../validation.mjs';

export function reject(records, id, reason, actor, now) {
  commandContext(actor, now, 'approver');
  const record = {
    ...target(records, id, 'submitted'), rejectionReason: trimmedText(reason),
    rejectedAt: now, rejectedBy: actor.id, status: 'rejected',
  };
  records.set(id, record);
  return { ...record };
}

import { commandContext, nonemptyString, positiveInteger, requireCondition, trimmedText } from '../validation.mjs';

export function submit(records, input, actor, now) {
  commandContext(actor, now, 'requester');
  requireCondition(input !== null && typeof input === 'object', 'Invalid input');
  const { id, item, quantity, requestedYen, reason } = input;
  requireCondition(nonemptyString(id) && !records.has(id), 'Invalid or duplicate ID');
  const record = {
    id, requesterId: actor.id, item: trimmedText(item),
    quantity: positiveInteger(quantity), requestedYen: positiveInteger(requestedYen),
    reason: trimmedText(reason), submittedAt: now, status: 'submitted',
  };
  records.set(id, record);
  return { ...record };
}

export function requireCondition(condition, message) {
  if (!condition) throw new Error(message);
}
export function nonemptyString(value) {
  return typeof value === 'string' && value.length > 0;
}
export function commandContext(actor, now, role) {
  requireCondition(actor !== null && typeof actor === 'object' && nonemptyString(actor.id) && actor.role === role, 'Invalid actor or role');
  requireCondition(Number.isSafeInteger(now) && now >= 0, 'Invalid timestamp');
}
export function positiveInteger(value) {
  requireCondition(Number.isSafeInteger(value) && value > 0, 'Expected positive safe integer');
  return value;
}
export function trimmedText(value) {
  requireCondition(typeof value === 'string' && value.trim().length > 0, 'Expected nonempty text');
  return value.trim();
}
export function target(records, id, status) {
  requireCondition(records.has(id), 'Unknown ID');
  const record = records.get(id);
  if (status !== undefined) requireCondition(record.status === status, 'Invalid transition');
  return record;
}

